begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_table('public','conversations','Conversation persistence exists');
select has_function('public','get_or_create_flight_conversation',array['uuid'],'Request-bound conversation open exists');
insert into auth.users(id,email) select ('20400000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'conversation-'||n||'@example.invalid' from generate_series(1,5) n;
insert into public.memberships(user_id,role) select ('20400000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=3 then 'admin' else 'member' end::public.member_role from generate_series(1,4) n;
insert into public.profiles(user_id,display_name,home_airport,pilot_designation) values('20400000-0000-4000-8000-000000000002','Conversation pilot','KPAO','licensed');
insert into public.flights(id,owner_id,departure_airport,destination_airport,departure_at,departure_timezone,aircraft_description,pilot_places,visibility)
select ('20410000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'20400000-0000-4000-8000-000000000001','KPAO','KSQL',now()+interval '2 days','UTC','Conversation C172',2,case when n=2 then 'PRIVATE' else 'NETWORK' end::public.flight_visibility from generate_series(1,5) n;
update public.flights set departure_at=clock_timestamp()+interval '3 seconds' where id='20410000-0000-4000-8000-000000000005';
insert into public.flight_recipients(flight_id,user_id) values('20410000-0000-4000-8000-000000000002','20400000-0000-4000-8000-000000000002');
insert into public.flight_requests(id,flight_id,requester_id) select ('20420000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('20410000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'20400000-0000-4000-8000-000000000002' from generate_series(1,5) n;
update public.flight_requests set status='accepted' where id::text like '20420000%' and id<>'20420000-0000-4000-8000-000000000003';
create function pg_temp.actor(n integer) returns text language sql as $$select set_config('request.jwt.claims',json_build_object('sub',('20400000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'role','authenticated','user_metadata',json_build_object('role','admin'))::text,true);$$;
create function pg_temp.open(n integer default 1) returns uuid language sql as $$select public.get_or_create_flight_conversation(('20420000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid);$$;
select ok((select prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='public.get_or_create_flight_conversation(uuid)'::regprocedure),'Creation uses fixed definer path');
select ok(not has_function_privilege('anon','public.get_or_create_flight_conversation(uuid)','EXECUTE'),'Anonymous RPC denied');
select ok(not has_table_privilege('anon','public.conversations','SELECT'),'No anonymous table access');
select ok(not has_table_privilege('authenticated','public.conversations','INSERT,UPDATE,DELETE'),'Members cannot mutate participants or closure');
select ok(not has_function_privilege('service_role','public.get_or_create_flight_conversation(uuid)','EXECUTE'),'No service-role RPC bypass');
set local role authenticated;
select set_config('request.jwt.claims','{}',true);
select throws_ok($$select pg_temp.open()$$,'42501',null,'Missing identity denied');
select pg_temp.actor(5);
select throws_ok($$select pg_temp.open()$$,'42501',null,'Missing membership denied');
select pg_temp.actor(3);
select throws_ok($$select pg_temp.open()$$,'42501',null,'Unrelated admin denied');
select is((select count(*)::integer from public.conversations where owner_id='20400000-0000-4000-8000-000000000001'),0,'Unrelated admin reads no threads');
select pg_temp.actor(2);
select throws_ok($$select pg_temp.open(3)$$,'42501',null,'Pending request cannot create');
select throws_ok($$select pg_temp.open(99)$$,'42501',null,'Missing request has same denial');
select throws_ok($$select public.get_or_create_flight_conversation(null)$$,'22023',null,'Null request rejected');
select lives_ok($$select pg_temp.open()$$,'Accepted requester opens thread');
select lives_ok($$select pg_temp.open(2)$$,'Selected PRIVATE requester opens thread');
select is((select count(*)::integer from public.conversations where owner_id='20400000-0000-4000-8000-000000000001'),2,'Only actual pair threads visible');
select is(pg_temp.open(),pg_temp.open(),'Repeated open returns same ID');
select pg_temp.actor(1);
select is(pg_temp.open(),(select id from public.conversations where flight_request_id='20420000-0000-4000-8000-000000000001'),'Owner sees same thread without profile requirement');
select throws_ok($$update public.conversations set owner_id=auth.uid()$$,'42501',null,'Direct identity update denied');
select throws_ok($$delete from public.conversations$$,'42501',null,'Direct history deletion denied');
reset role;
select throws_ok($$insert into public.conversations(flight_request_id,owner_id,requester_id) values('20420000-0000-4000-8000-000000000003','20400000-0000-4000-8000-000000000001','20400000-0000-4000-8000-000000000002')$$,'23514',null,'Privileged insert cannot bypass acceptance');
select throws_ok($$insert into public.conversations(flight_request_id,owner_id,requester_id) values('20420000-0000-4000-8000-000000000005','20400000-0000-4000-8000-000000000003','20400000-0000-4000-8000-000000000002')$$,'23514',null,'Privileged insert cannot forge owner');
select throws_ok($$insert into public.conversations(flight_request_id,owner_id,requester_id) values('20420000-0000-4000-8000-000000000001','20400000-0000-4000-8000-000000000001','20400000-0000-4000-8000-000000000002')$$,'23505',null,'Unique request prevents duplicate threads');
select throws_ok($$update public.conversations set requester_id='20400000-0000-4000-8000-000000000003'$$,'23514',null,'Privileged participant edits rejected');
select throws_ok($$delete from public.flight_requests where id='20420000-0000-4000-8000-000000000001'$$,'23503',null,'History prevents accidental request cascade');
update public.memberships set status='disabled',disabled_at=now(),disabled_reason='Fixture' where user_id='20400000-0000-4000-8000-000000000002';
set local role authenticated;
select pg_temp.actor(2);
select is((select count(*)::integer from public.conversations where owner_id='20400000-0000-4000-8000-000000000001'),0,'Disabled viewer loses history with retained JWT');
select throws_ok($$select pg_temp.open()$$,'42501',null,'Disabled viewer cannot open');
select pg_temp.actor(1);
select is((select count(*)::integer from public.conversations where owner_id='20400000-0000-4000-8000-000000000001'),2,'Active owner retains history with disabled counterpart');
select throws_ok($$select pg_temp.open()$$,'42501',null,'Disabled counterpart cannot support creation or reopening');
reset role;
update public.memberships set status='active',disabled_at=null,disabled_reason=null where user_id='20400000-0000-4000-8000-000000000002';
set local role authenticated;
select pg_temp.actor(2);
select public.withdraw_flight_request('20410000-0000-4000-8000-000000000001','20420000-0000-4000-8000-000000000001');
select ok((select closed_at is not null from public.conversations where flight_request_id='20420000-0000-4000-8000-000000000001'),'Accepted withdrawal atomically closes conversation');
select throws_ok($$select pg_temp.open()$$,'42501',null,'Withdrawal blocks reopen');
select public.submit_flight_interest('20410000-0000-4000-8000-000000000001');
select throws_ok($$select pg_temp.open()$$,'42501',null,'Pending resubmission cannot reopen');
select pg_temp.actor(1);
select public.decide_flight_request('20410000-0000-4000-8000-000000000001','20420000-0000-4000-8000-000000000001','accepted');
select ok((select closed_at is not null from public.conversations where flight_request_id='20420000-0000-4000-8000-000000000001'),'Acceptance alone does not recreate or reopen history');
select lives_ok($$select pg_temp.open()$$,'Explicit open after fresh acceptance permitted');
select ok((select closed_at is null from public.conversations where flight_request_id='20420000-0000-4000-8000-000000000001'),'Fresh acceptance can reopen same thread');
select public.change_flight_recipient('20410000-0000-4000-8000-000000000002','20400000-0000-4000-8000-000000000002',false);
select ok((select closed_at is not null from public.conversations where flight_request_id='20420000-0000-4000-8000-000000000002'),'PRIVATE removal closes existing thread');
select pg_temp.actor(2);
select is((select count(*)::integer from public.flights where id='20410000-0000-4000-8000-000000000002'),0,'Retained thread grants no PRIVATE flight read');
select is((select count(*)::integer from public.conversations where owner_id='20400000-0000-4000-8000-000000000001'),2,'Removed recipient retains own thread history');
select throws_ok($$select pg_temp.open(2)$$,'42501',null,'Removed recipient cannot reopen');
select pg_temp.actor(1);
select public.cancel_flight('20410000-0000-4000-8000-000000000001');
select ok((select closed_at is not null from public.conversations where flight_request_id='20420000-0000-4000-8000-000000000001'),'Flight cancellation atomically closes thread');
select throws_ok($$select pg_temp.open()$$,'42501',null,'Cancelled flight cannot reopen');
select lives_ok($$select pg_temp.open(4)$$,'Another accepted request has separate thread');
reset role;
update public.flights set status='completed' where id='20410000-0000-4000-8000-000000000004';
select ok((select closed_at is not null from public.conversations where flight_request_id='20420000-0000-4000-8000-000000000004'),'Completed flight closes thread');
select throws_ok($$update public.conversations set closed_at=null where flight_request_id='20420000-0000-4000-8000-000000000004'$$,'23514',null,'Privileged reopen cannot bypass closed flight');
select pg_sleep(greatest(0,extract(epoch from departure_at-clock_timestamp()))+0.01) from public.flights where id='20410000-0000-4000-8000-000000000005';
delete from public.profiles where user_id='20400000-0000-4000-8000-000000000002';
set local role authenticated;
select lives_ok($$select pg_temp.open(5)$$,'Past departure and absent profile do not erase established acceptance');
reset role;
select is((select count(*)::integer from public.conversations where owner_id='20400000-0000-4000-8000-000000000001'),4,'No duplicate threads or terminal-state creations');
select * from finish();
rollback;
